/** Minimal structural binding declarations for this project's Cloudflare runtime. */
interface D1Result<T=Record<string,unknown>>{results:T[];success:boolean;meta:Record<string,unknown>}
interface D1PreparedStatement{bind(...values:unknown[]):D1PreparedStatement;first<T=Record<string,unknown>>(column?:string):Promise<T|null>;all<T=Record<string,unknown>>():Promise<D1Result<T>>;run<T=Record<string,unknown>>():Promise<D1Result<T>>;raw<T=unknown[]>():Promise<T[]>}
interface D1Database{prepare(query:string):D1PreparedStatement;batch<T=Record<string,unknown>>(statements:D1PreparedStatement[]):Promise<D1Result<T>[]>;exec(query:string):Promise<{count:number;duration:number}>;dump():Promise<ArrayBuffer>}
interface Fetcher{fetch(request:Request|string,init?:RequestInit):Promise<Response>}
declare module 'cloudflare:workers'{export const env:{DB:D1Database;BUCKET:{put(key:string,value:ArrayBuffer,options?:{httpMetadata:{contentType:string}}):Promise<unknown>;get(key:string):Promise<{body:ReadableStream}|null>};GOOGLE_CALENDAR_ENABLED?:string;GOOGLE_CALENDAR_ID?:string;GOOGLE_CALENDAR_NAME?:string;GOOGLE_SERVICE_ACCOUNT_EMAIL?:string;GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY?:string;[key:string]:unknown}}
